<?php require_once __DIR__.'/../config/bootstrap.php';if(user())redirect('/gamestore/index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT id,name,email,password,role FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);unset($u['password']);$_SESSION['user']=$u;redirect($u['role']==='admin'?'/gamestore/admin/index.php':'/gamestore/index.php');}$error='E-mail ou senha incorretos.';}$pageTitle='Entrar';require __DIR__.'/../includes/header.php';?><div class="form-card"><h1 class="h3 fw-bold">Entrar</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="form-label">E-mail</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Senha</label><input class="form-control mb-3" type="password" name="password" required><button class="btn btn-neon w-100">Entrar</button></form><p class="mt-3 mb-0">Ainda não possui cadastro? <a href="register.php">Cadastre-se</a></p></div><?php require __DIR__.'/../includes/footer.php';?>
